    const { anchor, url } = await geocodePlace(args.address, bias, args.state)
    const bounds = geocodeBoundsForCentroid(bias)
    return {
      geocodeUrl: url,
      bounds,
      boundsCenteredOn: bias,
      deltaDegrees: 1.2,
      result: anchor,
      containsBoundsParam: url.includes('bounds='),
    }
  },
})

