    })

    return {
      routeId,
      disposition: 'generated',
      verdict: 'pass',
      provenance: 'scraped_promoted',
      geometryStatus: 'generated',
      routedMiles,
      claimedMiles,
      ratio: roundedRatio,
      pointCount: points.length,
      anchorCount: anchors.length,
      anchors,
      geometry: route.routePolyline,
      queuedForLever2: false,
      queuedForReview: false,
      llmCallCount: 0,
    }
  },
})

