        failedCondition: 'anchors' as const,
        geometryStatus: 'review' as const,
        anchorCount: geocoded.length,
        anchors: geocoded,
        pointCount: 0,
        degenerate: true,
        ratio: null,
        claimedMiles,
        routedMiles: 0,
